import{c as l,Q as o,j as u,m as g}from"./chunks/framework.DOi4mjdC.js";const c=JSON.parse('{"title":"Matmul性能优化策略总览","description":"","frontmatter":{},"headers":[{"level":1,"title":"Matmul性能优化策略总览","slug":"matmul性能优化策略总览"}],"relativePath":"guide/算子实践参考/优秀实践/Matmul性能调优案例/Matmul性能优化策略总览.md","filePath":"guide/算子实践参考/优秀实践/Matmul性能调优案例/Matmul性能优化策略总览.md"}'),q={name:"guide/算子实践参考/优秀实践/Matmul性能调优案例/Matmul性能优化策略总览.md"};function r(a,t,d,e,p,i){return o(),u("div",null,[...t[0]||(t[0]=[g('<h1 id="matmul性能优化策略总览" tabindex="-1">Matmul性能优化策略总览 <a class="header-anchor" href="#matmul性能优化策略总览" aria-label="Permalink to &quot;Matmul性能优化策略总览&quot;">​</a></h1><p>本节提供了一系列包含Matmul计算的算子性能调优案例，开发者可根据实际应用场景，参考相关案例中的优化方法和思路，应用于具体实践中。案例分为如下五类，各分类的简介请参见如下表格，详细内容请阅读后续章节。</p><ul><li><p>Tiling优化</p><p><strong>表 1</strong> Tiling优化策略总览</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;30.086991300869915%&quot;&gt;&lt;p&gt;分类&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;40.82591740825918%&quot;&gt;&lt;p&gt;适用场景&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;29.087091290870916%&quot;&gt;&lt;p&gt;相关案例&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;30.086991300869915%&quot;&gt;&lt;p&gt;Tiling优化：优化Tiling分核及基本块切分策略。&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;40.82591740825918%&quot;&gt;&lt;p&gt;数据量足够多的大Shape场景。&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;29.087091290870916%&quot;&gt;&lt;p&gt;&lt;a href=&quot;Matmul算子优化Tiling策略.md&quot;&gt;Matmul算子优化Tiling策略&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p></li><li><p>并行度优化</p><p><strong>表 2</strong> 并行度优化策略总览</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;30.086991300869915%&quot;&gt;&lt;p&gt;分类&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;40.82591740825918%&quot;&gt;&lt;p&gt;适用场景&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;29.087091290870916%&quot;&gt;&lt;p&gt;相关案例&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;30.086991300869915%&quot;&gt;&lt;p&gt;多核间任务并行：合理地将数据分配给不同的核来执行任务。&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;40.82591740825918%&quot;&gt;&lt;p&gt;矩阵的K轴较大、M轴和N轴相比K轴较小的场景。&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;29.087091290870916%&quot;&gt;&lt;p&gt;&lt;a href=&quot;Matmul高阶API使能多核切K.md&quot;&gt;Matmul高阶API使能多核切K&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;30.086991300869915%&quot;&gt;&lt;p&gt;多核间数据访问并行：优化多核数据并行访问机制，如多核场景同一内存数据的地址访问冲突优化，实现多核数据访问效率提升。&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;40.82591740825918%&quot;&gt;&lt;p&gt;多核执行Matmul，输入矩阵的K轴较大且K轴非全载的场景。&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;29.087091290870916%&quot;&gt;&lt;p&gt;&lt;a href=&quot;Matmul高阶API使能多核K轴错峰访问内存.md&quot;&gt;Matmul高阶API使能多核K轴错峰访问内存&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;30.086991300869915%&quot;&gt;&lt;p&gt;单核内流水并行：利用不同指令队列间的相互独立性和可并行执行特性，优化核内流水并行度。&lt;/p&gt; &lt;p&gt;&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;40.82591740825918%&quot;&gt;&lt;ol&gt;&lt;li&gt;算子的MMAD流水和FIXPIPE流水之间串行执行，同步等待的时间在算子整体执行耗时中占比较高。&lt;/li&gt;&lt;li&gt;MTE2 Bound且MTE2流水和其他流水串行执行。&lt;/li&gt;&lt;/ol&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;29.087091290870916%&quot;&gt;&lt;ol&gt;&lt;li&gt;&lt;a href=&quot;Matmul高阶API使能UnitFlag.md&quot;&gt;Matmul高阶API使能UnitFlag&lt;/li&gt;&lt;li&gt;&lt;a href=&quot;Matmul高阶API使能NBuffer33模板.md&quot;&gt;Matmul高阶API使能NBuffer33模板&lt;/li&gt;&lt;/ol&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p></li><li><p>内存优化</p><p><strong>表 3</strong> 内存优化策略总览</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;30.086991300869915%&quot;&gt;&lt;p&gt;分类&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;40.82591740825918%&quot;&gt;&lt;p&gt;适用场景&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;29.087091290870916%&quot;&gt;&lt;p&gt;相关案例&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;30.086991300869915%&quot;&gt;&lt;p&gt;内存共享与复用：通过Buffer的共享与缓存复用，减少重复的数据搬运带来的开销。&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;40.82591740825918%&quot;&gt;&lt;p&gt;MIX场景下，多个AIV的A矩阵或B矩阵GM地址相同，且多个AIV复用的A矩阵或B矩阵在L1 Buffer上全载。&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;29.087091290870916%&quot;&gt;&lt;p&gt;&lt;a href=&quot;Matmul高阶API使能IBShare模板共享A和B矩阵数据.md&quot;&gt;Matmul高阶API使能IBShare模板共享A和B矩阵数据&lt;/p&gt; &lt;p&gt;&lt;a href=&quot;Matmul高阶API使能IBShare模板共享B矩阵数据.md&quot;&gt;Matmul高阶API使能IBShare模板共享B矩阵数据&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;30.086991300869915%&quot;&gt;&lt;p&gt;内存对齐：确保处理的数据满足特定的对齐要求，针对非对齐数据使用不同的搬运策略，以提升数据搬运的效率。&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;40.82591740825918%&quot;&gt;&lt;p&gt;输入矩阵内轴非256字节对齐，且数据量较大的场景。&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;29.087091290870916%&quot;&gt;&lt;p&gt;&lt;a href=&quot;AIV核上的ND2NZ格式转换.md&quot;&gt;AIV核上的ND2NZ格式转换&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p></li><li><p>Scalar优化</p><p><strong>表 4</strong> Scalar优化策略总览</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;30.086991300869915%&quot;&gt;&lt;p&gt;分类&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;40.82591740825918%&quot;&gt;&lt;p&gt;适用场景&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;29.087091290870916%&quot;&gt;&lt;p&gt;相关案例&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;30.086991300869915%&quot;&gt;&lt;p&gt;Tiling常量化：在Kernel编译期间完成Matmul Tiling的计算，由变量转化为常量扩散到系统中，减少Scalar提升性能。&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;40.82591740825918%&quot;&gt;&lt;p&gt;Matmul初始化时的Scalar计算较多，影响指令头开销。&lt;/p&gt; &lt;p&gt;Matmul迭代之间的Scalar计算较多，阻塞MTE2流水。&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;29.087091290870916%&quot;&gt;&lt;p&gt;&lt;a href=&quot;Matmul高阶API使能Tiling全量常量化.md&quot;&gt;Matmul高阶API使能Tiling全量常量化&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;30.086991300869915%&quot;&gt;&lt;p&gt;纯Cube模式：减少消息处理机制带来额外的Scalar开销。&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;40.82591740825918%&quot;&gt;&lt;p&gt;相较于MIX模式，没有矢量计算，只有矩阵计算的场景。&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;29.087091290870916%&quot;&gt;&lt;p&gt;&lt;a href=&quot;Matmul高阶API使能纯Cube模式.md&quot;&gt;Matmul高阶API使能纯Cube模式&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p></li><li><p>搬运优化</p><p><strong>表 5</strong> 搬运优化策略总览</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;30.086991300869915%&quot;&gt;&lt;p&gt;分类&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;40.82591740825918%&quot;&gt;&lt;p&gt;适用场景&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;29.087091290870916%&quot;&gt;&lt;p&gt;相关案例&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;30.086991300869915%&quot;&gt;&lt;p&gt;搬运吞吐量优化：通过合理控制搬运数据块的大小，提升带宽利用效率，实现搬运效率的提升。&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;40.82591740825918%&quot;&gt;&lt;ol&gt;&lt;li&gt;MTE2循环搬运次数多的大shape场景。&lt;/li&gt;&lt;li&gt;输入和输出的数据量超过L2 Cache大小的场景。&lt;/li&gt;&lt;/ol&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;29.087091290870916%&quot;&gt;&lt;ol&gt;&lt;li&gt;&lt;a href=&quot;Matmul高阶API使能MDL模板.md&quot;&gt;Matmul 高阶API使能MDL模板&lt;/li&gt;&lt;li&gt;&lt;a href=&quot;Matmul高阶API使能L2-Cache切分.md&quot;&gt;Matmul高阶API使能L2 Cache切分&lt;/li&gt;&lt;/ol&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;30.086991300869915%&quot;&gt;&lt;p&gt;预加载搬运：预加载需要搬运的数据块，减少流水之间的间隙。&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;40.82591740825918%&quot;&gt;&lt;p&gt;MTE2流水间隙较大，且M或N数值较大的场景。&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;29.087091290870916%&quot;&gt;&lt;p&gt;&lt;a href=&quot;Matmul高阶API使能MTE2-Preload.md&quot;&gt;Matmul高阶API使能MTE2 Preload&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p></li></ul>',3)])])}const h=l(q,[["render",r]]);export{c as __pageData,h as default};
